import data from "../data/circuit-outlines.json";
import type { CircuitOutline } from "../types/f1";

// Track outlines generated by scripts/build-circuit-outlines.mjs from the open
// f1-circuits GeoJSON (MIT, © Tomislav Bacinger). Keyed by f1db circuitId;
// only circuits present in that dataset have one.
// JSON arrays infer as number[], not the [x, y] tuple, hence the widening cast.
const outlines = data.circuits as unknown as Record<string, CircuitOutline>;

export function circuitOutline(circuitId: string): CircuitOutline | null {
  return outlines[circuitId] ?? null;
}
